await cu.click('Card');
await cu.click('Submit');
return await page.evaluate(() => ({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: document.body.innerText.includes('Thank') ? document.body.innerText.match(/[^.!?]*thank[^.!?]*[.!?]/i)?.[0] : document.body.innerText.slice(-500), values: [], answer: document.body.innerText.match(/[^.!?]*thank[^.!?]*[.!?]/i)?.[0] || ''}));

await page.goto('https://practice.expandtesting.com/form-validation');
await cu.fill('Contact Name', 'Alex Example');
await cu.fill('Contact number PickUp Date', '012-3456789');
await page.getByLabel('Contact number PickUp Date').nth(1).fill('15-01-2030');
await page.getByLabel('Payment Method').selectOption({label:'Card'});
await cu.click('Register');
return await page.evaluate(() => { const text = document.body.innerText; const sentence = text.match(/[^\n]*thank[^\n]*[.!]?/i)?.[0] || ''; return cu.claim({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: sentence || text.slice(-500), values: ['Alex Example','012-3456789','15 January 2030','Card'], answer: sentence}); });
